CREATE OR REPLACE FUNCTION private.crm_dynamic_matches(customer jsonb, filters jsonb, catalogs jsonb) RETURNS boolean LANGUAGE plpgsql STABLE SET search_path=public AS $$ DECLARE f jsonb; c jsonb; v jsonb; typ text; BEGIN IF jsonb_typeof(filters) IS DISTINCT FROM 'array' OR jsonb_array_length(filters)>30 THEN RAISE EXCEPTION 'Bộ lọc chuyên sâu không hợp lệ.'; END IF; FOR f IN SELECT value FROM jsonb_array_elements(filters) LOOP IF coalesce(f->>'id','')='' THEN CONTINUE; END IF; SELECT x INTO c FROM jsonb_array_elements(catalogs) x WHERE x->>'id'=f->>'id'; IF c IS NULL OR NOT private.crm_scope_matches(c->'config',nullif(customer->>'group_id','')::uuid,nullif(customer->>'segment_id','')::uuid) THEN RETURN false; END IF; IF c->>'kind'<>'custom_field' THEN IF NOT coalesce(customer->'related_ids','[]') ? (f->>'id') THEN RETURN false; END IF; CONTINUE; END IF; typ:=c->'config'->>'field_type'; v:=customer->'custom_values'->(f->>'id'); IF v IS NULL OR v='null'::jsonb THEN RETURN false; END IF;
IF nullif(f->>'min','') IS NOT NULL THEN IF typ IN ('number','money') THEN IF jsonb_typeof(v)<>'number' OR (v#>>'{}')::numeric<(f->>'min')::numeric THEN RETURN false; END IF; ELSIF typ='date' THEN IF (v#>>'{}')::date<(f->>'min')::date THEN RETURN false; END IF; ELSE RAISE EXCEPTION 'Trường không hỗ trợ lọc khoảng.'; END IF; END IF;
IF nullif(f->>'max','') IS NOT NULL THEN IF typ IN ('number','money') THEN IF jsonb_typeof(v)<>'number' OR (v#>>'{}')::numeric>(f->>'max')::numeric THEN RETURN false; END IF; ELSIF typ='date' THEN IF (v#>>'{}')::date>(f->>'max')::date THEN RETURN false; END IF; ELSE RAISE EXCEPTION 'Trường không hỗ trợ lọc khoảng.'; END IF; END IF;
IF nullif(f->>'contains','') IS NOT NULL AND position(lower(f->>'contains') in lower(v#>>'{}'))=0 THEN RETURN false; END IF;
IF f ? 'value' AND f->'value' NOT IN ('null'::jsonb,'""'::jsonb,'[]'::jsonb) THEN IF typ='multiselect' THEN IF jsonb_typeof(f->'value')='array' THEN IF NOT v @> (f->'value') THEN RETURN false; END IF; ELSIF NOT v ? (f->>'value') THEN RETURN false; END IF; ELSIF v IS DISTINCT FROM f->'value' THEN RETURN false; END IF; END IF; END LOOP; RETURN true; END $$;
CREATE OR REPLACE FUNCTION private.crm_catalogs_at(at_ timestamptz) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce(jsonb_agg(snapshot),'[]') FROM (SELECT DISTINCT ON(catalog_id) snapshot FROM crm_catalog_versions WHERE recorded_at<at_ ORDER BY catalog_id,recorded_at DESC,id DESC) q $$;
DO $$ DECLARE d text; BEGIN SELECT pg_get_functiondef('public.crm_report_filtered(date,date,boolean,uuid,uuid,text,uuid,uuid,uuid,uuid,uuid,uuid,boolean)'::regprocedure) INTO d; d:=replace(d,'crm_report_filtered(','crm_report_dynamic('); d:=replace(d,'_export boolean DEFAULT false','_filters jsonb DEFAULT ''[]''::jsonb, _export boolean DEFAULT false'); d:=replace(d,'r jsonb; cs jsonb;','r jsonb; cats jsonb; cs jsonb;'); d:=replace(d,'hi:=(r->>''as_of'')::timestamptz;','hi:=(r->>''as_of'')::timestamptz; cats:=private.crm_catalogs_at(hi);'); d:=replace(d,'WHERE (_segment IS NULL','WHERE private.crm_dynamic_matches(x,_filters,cats) AND (_segment IS NULL'); d:=replace(d,'''customers'',cs,''schedules''','''catalogs'',cats,''customers'',cs,''schedules'''); IF position('_filters jsonb' in d)=0 OR position('private.crm_dynamic_matches' in d)=0 OR position('cats:=private.crm_catalogs_at' in d)=0 THEN RAISE EXCEPTION 'Missing report extension point'; END IF; EXECUTE d; END $$;
REVOKE ALL ON FUNCTION public.crm_report_dynamic(date,date,boolean,uuid,uuid,text,uuid,uuid,uuid,uuid,uuid,uuid,jsonb,boolean) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.crm_report_dynamic(date,date,boolean,uuid,uuid,text,uuid,uuid,uuid,uuid,uuid,uuid,jsonb,boolean) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.crm_read_dynamic(_mine boolean DEFAULT true,_owner uuid DEFAULT NULL,_search text DEFAULT '',_archived boolean DEFAULT false,_group uuid DEFAULT NULL,_segment uuid DEFAULT NULL,_priority uuid DEFAULT NULL,_filters jsonb DEFAULT '[]') RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE r jsonb; cs jsonb; cats jsonb; BEGIN r:=crm_read(_mine,_owner,_search,_archived); cats:=private.crm_catalogs_at(now()+interval '1 microsecond'); SELECT coalesce(jsonb_agg(x),'[]') INTO cs FROM jsonb_array_elements(r->'customers') x WHERE (_group IS NULL OR x->>'group_id'=_group::text) AND (_segment IS NULL OR x->>'segment_id'=_segment::text) AND (_priority IS NULL OR x->>'priority_id'=_priority::text) AND private.crm_dynamic_matches(x,_filters,cats); RETURN r||jsonb_build_object('customers',cs,'schedules',(SELECT coalesce(jsonb_agg(x),'[]') FROM jsonb_array_elements(r->'schedules') x WHERE EXISTS(SELECT 1 FROM jsonb_array_elements(cs) c WHERE c->>'id'=x->>'customer_id')),'contacts',(SELECT coalesce(jsonb_agg(x),'[]') FROM jsonb_array_elements(r->'contacts') x WHERE EXISTS(SELECT 1 FROM jsonb_array_elements(cs) c WHERE c->>'id'=x->>'customer_id'))); END $$;
REVOKE ALL ON FUNCTION public.crm_read_dynamic(boolean,uuid,text,boolean,uuid,uuid,uuid,jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.crm_read_dynamic(boolean,uuid,text,boolean,uuid,uuid,uuid,jsonb) TO authenticated,service_role;
REVOKE ALL ON FUNCTION private.crm_dynamic_matches(jsonb,jsonb,jsonb),private.crm_catalogs_at(timestamptz) FROM PUBLIC,anon,authenticated;